extern crate verus;
use verus::prelude::*;

verus! {

    /// Given a total count `n>=1` and a selected count `0<=k<=n`,
    /// returns a Vec of length 2, `[x_min, x_max]`, describing
    /// the possible number of “good” unselected items.
    #[verifier(decreases(n as int, k as int))]
    pub fn solve(n: i8, k: i8) -> Vec<i8> {
        // pre‐conditions
        requires(n >= 1);
        requires(0 <= k && k <= n);

        // post‐conditions
        ensures(|res: Vec<i8>| {
            // exactly two elements
            res.len() == 2
            // nonnegative
            && 0 <= res[0] && 0 <= res[1]
            // ordered
            && res[0] <= res[1]
            // both ≤ number of unselected items
            && res[0] <= n - k
            && res[1] <= n - k
            // and they satisfy the problem’s case‐split
            && (if k == 0 || k == n {
                    // if no items or all items are selected,
                    // then both must be zero
                    res[0] == 0 && res[1] == 0
                } else {
                    // otherwise x_min = 1, x_max = min(n-k, 2*k)
                    res[0] == 1
                    && res[1] == std::cmp::min(n - k, 2*k)
                })
        });

        if k == 0 || k == n {
            // No unselected “good” items if none or all are selected.
            vec![0, 0]
        } else {
            // Compute the two‐times‐k and (n-k) in a wider type to avoid overflow,
            // then take the min and cast back to i8.
            let unselected_i16: i16 = (n - k) as i16;
            let twice_k_i16: i16 = (k as i16) * 2;
            let max_good_unselected_i16 = std::cmp::min(unselected_i16, twice_k_i16);
            let max_good_unselected: i8 = max_good_unselected_i16 as i8;
            vec![1, max_good_unselected]
        }
    }

}